#!/bin/bash

# $SINGLE_PRECISION is ON, set $HOOMD_LONGREAL_SIZE to 32, else 64
if [ "$SINGLE_PRECISION" = "ON" ]; then
    HOOMD_LONGREAL_SIZE=32
    BUILD_DIR=.build/hoomd
else
    HOOMD_LONGREAL_SIZE=64
    BUILD_DIR=.build/hoomd-double
fi

rm -rf $BUILD_DIR

cmake -B $BUILD_DIR -G Ninja -S hoomd-blue -DENABLE_GPU=$ENABLE_GPU -DBUILD_HPMC=OFF -DBUILD_METAL=OFF -DHOOMD_LONGREAL_SIZE=$HOOMD_LONGREAL_SIZE -DENABLE_TBB=OFF -DCMAKE_CUDA_FLAGS="--compiler-bindir=$CC" -DCUDA_ARCH_LIST=$CUDAARCHS -DCMAKE_CXX_STANDARD=17 -DCMAKE_CXX_COMPILER=$CXX -DCMAKE_BUILD_TYPE=RelWithDebInfo